/**
 * Settings → Remote pi worker: where the agent reaches a pi installed on
 * another host, over SSH only.
 *
 * Unlike Codex and Claude workers, nothing runs inside the app-server for this
 * integration: the BFF itself shells out to `ssh` (see `runner.ts`), so the
 * settings live on the BFF's own `bff-data` volume and never cross the upstream
 * connection. The private key is lettuce-held: generated by the BFF
 * (`PiService.generateKeyPair`, the recommended path) or pasted, stored 0600 on
 * that volume, and never returned to a browser. The browser sees
 * `PublicPiSettings`: `hasKey` plus the PUBLIC half (`publicKey`) — a public key
 * is safe to serve, and it is exactly the line the operator pastes into the
 * remote host's `authorized_keys`.
 *
 * (An ssh-agent auth mode existed on this branch and was dropped by operator
 * decision on 2026-10-06: unattended simplicity over zero-storage custody.)
 *
 * `pathPrepend` is not cosmetic: a non-interactive remote shell gets a minimal
 * PATH that usually misses pi and node entirely (measured before this was
 * built), so the dispatch command carries a PATH
 * prefix. It is normalized on the way in and on the way out because a trailing
 * slash is a natural thing to type and a *program* can see it: PATH search
 * composes `$dir/pi`, and a launcher that finds its own install directory by
 * stripping path elements off `$0` lands one level off (`bin//pi` → `bin`
 * instead of `agent`) and fails naming a file nobody asked for.
 */

/** Collapse a typed PATH prefix to what a PATH search should actually use. */
export function normalizePathPrepend(value: string): string {
  return value
    .split(":")
    .map((entry) => entry.trim().replace(/\/+$/, ""))
    .filter((entry) => entry !== "")
    .join(":");
}

/** What runs when `command` is empty — the program this integration was built for. */
export const DEFAULT_PI_COMMAND = "pi";

/**
 * Split the `command` field into the words of a remote command.
 *
 * The field is one line on purpose: "use `pi-bolt`, and always with
 * `--thinking high`" is one thought, and two fields would leave the operator
 * wondering which of them the quoting belongs in. So we do the splitting job the
 * remote shell would: split on the blanks sh splits on (space, tab, newline —
 * nothing else, so a pasted non-breaking space is part of a word here too),
 * honour `'…'` (literal, backslash included), `"…"` (a backslash escapes only
 * `$ \` ` ` and `"`, as sh does) and backslash escapes between words, and hand
 * back whole words. Each word then goes to the remote quoted when it needs it
 * (`shqWord` in `runner.ts`), so a metacharacter typed here stays a literal —
 * this field adds no shell surface beyond what Workdir and PATH prefix already
 * are. Nothing is expanded remotely: a path must be absolute, since `~` and `$`
 * arrive as literal characters.
 *
 * Refuses what cannot be a command: an unclosed quote, a trailing backslash, a
 * control character (a newline here would tear the remote compound command
 * apart), an empty word, which the remote would try to exec, and the flags the
 * runner appends after these words — `--mode json` and `--approve` are how a run
 * stays parseable and never blocks on a prompt, and `--` alone would turn them
 * into positional arguments.
 */
export function parsePiCommand(value: string): string[] {
  const text = value.trim();
  if (!text) return [];
  for (const ch of text) {
    const code = ch.codePointAt(0) ?? 0;
    if (code < 32 || code === 127) {
      throw new InvalidPiSettingsError("`command` must not contain control characters");
    }
  }
  const words: string[] = [];
  let word = "";
  let started = false;
  let quote: "'" | '"' | null = null;
  let i = 0;
  // A backslash always consumes the character after it, which is why this walks
  // by index rather than with for..of.
  while (i < text.length) {
    const ch = text[i]!;
    i += 1;
    if (quote === "'") {
      // Inside single quotes a backslash is a backslash — exactly the sh rule,
      // which is the whole reason the words are quoted on the way out.
      if (ch === "'") quote = null;
      else word += ch;
      continue;
    }
    if (quote === '"') {
      if (ch === '"') {
        quote = null;
      } else if (ch === "\\" && i < text.length && '"$\\`'.includes(text[i]!)) {
        // The sh rule inside double quotes: a backslash escapes only these four.
        // Dropping it before anything else is how `--note "a\b"` loses a character
        // the shell would have kept.
        word += text[i];
        i += 1;
      } else word += ch;
      continue;
    }
    if (ch === "'") {
      quote = "'";
      started = true;
    } else if (ch === '"') {
      quote = '"';
      started = true;
    } else if (ch === "\\") {
      if (i >= text.length) {
        throw new InvalidPiSettingsError("`command` ends with a backslash");
      }
      word += text[i];
      i += 1;
      started = true;
    } else if (ch === " " || ch === "\t" || ch === "\n") {
      if (started) {
        words.push(word);
        word = "";
        started = false;
      }
    } else {
      word += ch;
      started = true;
    }
  }
  if (quote) throw new InvalidPiSettingsError("`command` has an unclosed quote");
  if (started) words.push(word);
  if (words.some((w) => w === "")) {
    throw new InvalidPiSettingsError("`command` must not contain an empty word");
  }
  const ours = words.find((w) => PI_COMMAND_RESERVED.includes(w));
  if (ours) {
    throw new InvalidPiSettingsError(
      `\`command\` must not use ${ours} — the run adds its own ${
        ours === "--" ? "arguments" : "flag"
      } after yours`,
    );
  }
  return words;
}

/** The words the runner appends itself, and so the ones this field may not use. */
const PI_COMMAND_RESERVED = ["--", "--mode", "--approve", "--session", "--model"];

/** The words to run: the configured command, or `pi` when nothing is configured. */
export function piCommandWords(command: string | null | undefined): string[] {
  const words = command ? parsePiCommand(command) : [];
  return words.length ? words : [DEFAULT_PI_COMMAND];
}

export interface PiSettings {
  /** Whether the pi tools exist at all (the `pi` profile token must also be on). */
  enabled: boolean;
  host: string;
  port: number;
  user: string;
  /** Private key in PEM text form. Held by lettuce, never returned to a browser. */
  privateKey: string | null;
  /**
   * Who made the stored key: lettuce (`generateKeyPair`) or a paste. The
   * Settings form shows one flow at a time and must not claim it generated a
   * key it was handed; never inferred from the PEM, only recorded when it
   * happens.
   */
  keySource: "generated" | "pasted";
  /**
   * Public half, derived or generated by the service (never trusted from the
   * browser). Safe to serve: this is the `authorized_keys` line for the remote.
   */
  publicKey: string | null;
  /** Prepended to PATH in every remote command, e.g. `/opt/node/bin:/opt/pi/bin`. */
  pathPrepend: string;
  /**
   * The program to run on the remote host with any fixed arguments, as one line:
   * `pi-bolt`, `/opt/pi/bin/pi-bolt --thinking high`. Empty means `pi`. We split
   * and quote it ourselves (`parsePiCommand`), and our own flags come after
   * whatever is typed here, so the json stream a run parses survives a typo in
   * this field: the flags that could clash with ours are refused at save time.
   */
  command: string;
  /** Absolute directory pi runs in on the remote host. */
  workdir: string;
  /** Optional pi model id; null lets the remote pi use its own default. */
  model: string | null;
  /** Run budget guards (0 = off): a run over either cancels itself, remotely. */
  maxEvents: number;
  maxRuntimeMinutes: number;
}

/** What the browser sees: the key is reduced to whether one is set. */
export type PublicPiSettings = Omit<PiSettings, "privateKey"> & { hasKey: boolean };

export const DEFAULT_PI_SETTINGS: PiSettings = {
  enabled: false,
  host: "",
  port: 22,
  user: "",
  privateKey: null,
  keySource: "generated",
  publicKey: null,
  pathPrepend: "",
  command: DEFAULT_PI_COMMAND,
  workdir: "",
  model: null,
  maxEvents: 200_000,
  maxRuntimeMinutes: 0,
};

export class InvalidPiSettingsError extends Error {}

export function toPublicPiSettings(settings: PiSettings): PublicPiSettings {
  const { privateKey, ...rest } = settings;
  return { ...rest, hasKey: privateKey !== null };
}

/** Lenient: a missing, hand-edited or older file still loads, with defaults filling gaps. */
export function parsePiSettings(text: string | null): PiSettings {
  if (!text) return { ...DEFAULT_PI_SETTINGS };
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return { ...DEFAULT_PI_SETTINGS };
  }
  if (!raw || typeof raw !== "object") return { ...DEFAULT_PI_SETTINGS };
  const r = raw as Record<string, unknown>;
  return {
    enabled: r.enabled === true,
    host: typeof r.host === "string" ? r.host : "",
    port: typeof r.port === "number" && r.port >= 1 && r.port <= 65535 ? r.port : 22,
    user: typeof r.user === "string" ? r.user : "",
    privateKey: typeof r.privateKey === "string" && r.privateKey ? r.privateKey : null,
    keySource: r.keySource === "pasted" ? "pasted" : "generated",
    publicKey: typeof r.publicKey === "string" && r.publicKey ? r.publicKey : null,
    pathPrepend: typeof r.pathPrepend === "string" ? normalizePathPrepend(r.pathPrepend) : "",
    // A record from before the field exists keeps working (empty runs `pi`), and
    // a hand-edited value that cannot be tokenized is dropped rather than making
    // every later run fail on a file nobody can see in the UI.
    command: commandOrFallback(r.command),
    workdir: typeof r.workdir === "string" ? r.workdir : "",
    model: typeof r.model === "string" && r.model ? r.model : null,
    // Absent means "stored before budgets existed": ship armed — the 200k
    // event net is what would have caught the 8.2 M-event incident.
    // An explicit 0 is still the operator's "off".
    maxEvents:
      r.maxEvents === undefined
        ? 200_000
        : Number.isInteger(r.maxEvents) && Number(r.maxEvents) > 0
          ? Number(r.maxEvents)
          : 0,
    maxRuntimeMinutes:
      Number.isInteger(r.maxRuntimeMinutes) && Number(r.maxRuntimeMinutes) > 0
        ? Number(r.maxRuntimeMinutes)
        : 0,
  };
}

export function renderPiSettings(settings: PiSettings): string {
  return `${JSON.stringify(settings, null, 2)}\n`;
}

/**
 * Merge a browser update into the saved settings. `privateKey` is only
 * replaced when the body carries a non-empty string — an absent or empty one
 * keeps the stored key, so the form can show `hasKey` without holding the key.
 * Throws InvalidPiSettingsError on anything unusable.
 */
export function applyPiSettingsUpdate(current: PiSettings, body: unknown): PiSettings {
  if (!body || typeof body !== "object") throw new InvalidPiSettingsError("Expected a JSON object");
  const r = body as Record<string, unknown>;

  const next: PiSettings = { ...current };
  if ("enabled" in r) {
    if (typeof r.enabled !== "boolean")
      throw new InvalidPiSettingsError("`enabled` must be true or false");
    next.enabled = r.enabled;
  }
  if (typeof r.host === "string") next.host = r.host.trim();
  if (typeof r.user === "string") next.user = r.user.trim();
  if (next.host && !isValidPiHost(next.host)) {
    throw new InvalidPiSettingsError("`host` must be a hostname or an IP address");
  }
  if (next.user && !isValidPiUser(next.user)) {
    throw new InvalidPiSettingsError("`user` must be a login name");
  }
  if ("port" in r) {
    const port = Number(r.port);
    if (!Number.isInteger(port) || port < 1 || port > 65535) {
      throw new InvalidPiSettingsError("`port` must be 1-65535");
    }
    next.port = port;
  }
  if ("pathPrepend" in r) {
    if (typeof r.pathPrepend !== "string")
      throw new InvalidPiSettingsError("`pathPrepend` must be a string");
    next.pathPrepend = normalizePathPrepend(r.pathPrepend);
  }
  if ("command" in r) {
    if (typeof r.command !== "string")
      throw new InvalidPiSettingsError("`command` must be a string");
    // Empty is the operator asking for the default back, not an empty command.
    const command = r.command.trim();
    parsePiCommand(command);
    next.command = command || DEFAULT_PI_COMMAND;
  }
  if ("workdir" in r) {
    if (typeof r.workdir !== "string")
      throw new InvalidPiSettingsError("`workdir` must be a string");
    next.workdir = r.workdir.trim();
  }
  if ("model" in r) {
    if (r.model !== null && typeof r.model !== "string") {
      throw new InvalidPiSettingsError("`model` must be a string or null");
    }
    next.model = typeof r.model === "string" && r.model.trim() ? r.model.trim() : null;
  }
  for (const field of ["maxEvents", "maxRuntimeMinutes"] as const) {
    if (field in r) {
      const n = Number(r[field]);
      if (!Number.isInteger(n) || n < 0 || n > (field === "maxEvents" ? 1_000_000 : 1440)) {
        throw new InvalidPiSettingsError(`\`${field}\` must be an integer 0..limit (0 = off)`);
      }
      next[field] = n;
    }
  }
  if (typeof r.privateKey === "string" && r.privateKey.trim()) {
    const key = r.privateKey.trimEnd();
    if (!key.startsWith("-----BEGIN")) {
      throw new InvalidPiSettingsError("`privateKey` must be a PEM private key (-----BEGIN …)");
    }
    next.privateKey = `${key}\n`;
    // A new PEM invalidates whatever public half was on record; the service
    // re-derives it from the stored key right after saving.
    if (key !== current.privateKey?.trimEnd()) next.publicKey = null;
    // Custody is recorded, never inferred, and never claimed back: a pasted key
    // stays "pasted" until generateKeyPair replaces it.
    next.keySource = "pasted";
  }

  if (next.enabled) {
    if (!next.host)
      throw new InvalidPiSettingsError("`host` is required to enable the remote pi worker");
    if (!next.user)
      throw new InvalidPiSettingsError("`user` is required to enable the remote pi worker");
    if (!next.workdir.startsWith("/")) {
      throw new InvalidPiSettingsError("`workdir` must be an absolute path on the remote host");
    }
    if (!next.privateKey) {
      throw new InvalidPiSettingsError("a private key is required — generate one or paste a PEM");
    }
  }
  return next;
}

/** A stored `command` is either usable or absent — never a run that cannot start. */
function commandOrFallback(value: unknown): string {
  if (typeof value !== "string") return DEFAULT_PI_COMMAND;
  const command = value.trim();
  if (!command) return DEFAULT_PI_COMMAND;
  try {
    parsePiCommand(command);
  } catch {
    return DEFAULT_PI_COMMAND;
  }
  return command;
}

/** Whether a saved settings blob is complete enough to dispatch runs with. */
export function piConfigured(settings: PiSettings): boolean {
  return (
    settings.enabled &&
    settings.host !== "" &&
    settings.user !== "" &&
    settings.workdir.startsWith("/") &&
    settings.privateKey !== null
  );
}

/**
 * What may stand where ssh expects a host or a login name.
 *
 * Both end up as one argv element, `user@host`, and ssh reads an element that
 * starts with `-` as an option: a host of `-oProxyCommand=…` is a command line
 * on the BFF's side of the connection, in the container that holds the key.
 * `--` before the destination (`buildSshArgs`) is the mechanical fix; these are
 * the same statement made where the operator can read the refusal. A name is
 * letters, digits, dots, hyphens and underscores (plus colons for a bare IPv6
 * address) and never begins with a hyphen.
 */
const PI_HOST = /^[A-Za-z0-9_.:][A-Za-z0-9_.:-]*$/;
const PI_USER = /^[A-Za-z0-9_.][A-Za-z0-9_.-]*\$?$/;

export function isValidPiHost(host: string): boolean {
  return host.length <= 253 && PI_HOST.test(host);
}

export function isValidPiUser(user: string): boolean {
  return user.length <= 64 && PI_USER.test(user);
}

/** `user@host`, port implicit when 22 (ssh's own default). */
export function piTarget(settings: PiSettings): string {
  return `${settings.user}@${settings.host}`;
}
